SourceCode.Declaration:
abstract class TFMLogicContextDataContract
{
    ClassName               logicContextCls;
    TFMLogicContextObject   obj;
    Description255          objDesc;
    str                     inputsAndOutputs;

}

Method.Source:
protected TFMLogicContextObject contractObject()
{
    SysDictClass    sdc;
    if (!obj)
    {
        sdc = new SysDictClass(className2Id(logicContextCls));
        obj = sdc.makeObject();
        obj.parmDataContract(this);
    }
    return obj;
}

public ClassName parmLogicContextClass(ClassName _logicContextCls = logicContextCls)
{
    SysDictClass    sdc = new SysDictClass(className2Id(logicContextCls));
    SetEnumerator   sEnum;
    str             typesHandled;

    TFMDescriptionAttribute descAttr;
    logicContextCls = _logicContextCls;
    if (!sdc)
    {
        return logicContextCls;
    }
    descAttr = sdc.getAttribute(classStr(TFMDescriptionAttribute));
    if (descAttr)
    {
        objDesc = descAttr.parmDescription();
    }



    if (this.contractObject())
    {
        obj.parmDataContract(this);

        sEnum = obj.inputTypes().getEnumerator();
        while (sEnum.moveNext())
        {
            typesHandled += (typesHandled ? ', ' : '') + strFmt('%1',sEnum.current());
        }
        typesHandled += '<br>' + strFmt("@TFM:Takes1inputs",(obj.noOfInputs() == -1 ? "@TFM:Infinite" : int2Str(obj.noOfInputs())));

        inputsAndOutputs = '<table><tr><th style="padding: 4px"><b><u>'+ "@TFM:Inputs" +'</u></b></th><th style="padding: 4px"><b><u>'+"@TFM:Output"+'</u></b></th></tr><tr><td style="padding: 4px">'+(obj.noOfInputs() == 0 ? strFmt('%1',TFMLogicContextTypes::None) : typesHandled)+'</td><td style="padding: 4px">'+strFmt('%1', obj.outputType())+'</td></tr></table>';
    }
    return logicContextCls;
}

public TFMLogicContextTypes outputType()
{
    if (!this.contractObject())
    {
        return TFMLogicContextTypes::None;
    }
    return obj.outputType();
}

public Set inputTypes()
{
    Set retset = new Set(Types::Enum);
    if (this.contractObject())
    {
        retset = obj.inputTypes();
    }
    return retset;
}

public int noOfinputs()
{
    int ret = 0;
    if (this.contractObject())
    {
        ret = obj.noOfinputs();
    }
    return ret;
}

/// <summary>
/// Which text should the node display on the User Interface
/// </summary>
/// <returns>A string with the name to display for the node.</returns>
public str displayValue()
{
    str ret = this.contractObject().Name();
    return ret;
}

public str detailsValue()
{
    str ret;
    //ret = '<i>'+ objDesc + '</i>';

    return ret;
}
